// Pointer Arithmetic Precedence
int arr[2] = {10, 20};
int *p = arr;

// Postfix '++' binds tighter than '*'
// 1. Value 10 is read (dereference *p)
// 2. p is incremented (p++)
int val1 = *p++; // val1 = 10, p points to 20

// Prefix '++' evaluates first
// 1. p is incremented (p now points past 20)
// 2. The new *p is dereferenced
int val2 = *++p; // Undefined behavior (points past end of array)


// Precedence Trap: Bitwise vs Comparison
// '&' has lower precedence than '=='
#define MASK_A 0x1
#define MASK_B 0x2
int flags = MASK_A;

// BUG: Evaluates (MASK_A == MASK_B) first (0)
// Then: (flags & 0) -> 0
if (flags & MASK_A == MASK_B) {}

// Correct Precedence: Parentheses force order
if ((flags & MASK_A) == MASK_B) {} 
if ((flags & MASK_A)) {} // Check if flag is set


// Macro Precedence Failure
#define SQUARE(x) x * x
int a = 5;

// Expansion: 10 / 5 * 5 (left-to-right associativity)
// Result: 50. Expected: 4
int result_fail = 10 / SQUARE(a); 

// Safe Macro Definition (Mandatory Parentheses)
#define SAFE_SQUARE(x) ((x) * (x))
int result_ok = 10 / SAFE_SQUARE(a); // Result: 10 / 25
